import random, itertools, math, time

def has_c4(edges, A, B):
    neighA={a:set() for a in A}
    for a,b in edges: neighA[a].add(b)
    for a1,a2 in itertools.combinations(A,2):
        if len(neighA[a1]&neighA[a2])>=2:
            return True
    return False

def greedy(a=8,b=9,target=28,tries=10000):
    A=list(range(a)); B=list(range(a,a+b))
    all_edges=[(i,j) for i in A for j in B]
    best=[]
    for t in range(tries):
        edges=[]
        # maintain pair used between B? adding edge (u,v), for C4 no A pair share B equivalently no pair of A for each B? let's simple
        order=all_edges[:]
        random.shuffle(order)
        neighA=[set() for _ in A]
        for (u,v) in order:
            ok=True
            # for every existing neighbor w of u, no other A connected to both v and w
            for u2 in A:
                if u2!=u and v in neighA[u2] and (neighA[u] & neighA[u2]):
                    ok=False; break
            if ok:
                edges.append((u,v)); neighA[u].add(v)
                if len(edges)>=target: return edges
        if len(edges)>len(best):
            best=edges; print('best',len(best),t)
    return best

