import random, itertools, collections, time
n=17
all_edges=[(i,j) for i in range(n) for j in range(i+1,n)]

def can_add(adj,u,v):
    # adding creates cycle length dist(u,v)+1; require current dist >=5 or inf (no dist <=4)
    if v in adj[u]: return False
    # BFS depth 4 from u
    seen={u}; frontier=[u]
    for d in range(1,5):
        nf=[]
        for x in frontier:
            for y in adj[x]:
                if y==v:
                    return False
                if y not in seen:
                    seen.add(y); nf.append(y)
        frontier=nf
    return True

def girth(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    g=999
    for s in range(n):
        dist=[-1]*n; par=[-1]*n; dist[s]=0
        q=collections.deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g, dist[u]+dist[v]+1)
    return None if g==999 else g

def four_colorable(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    order=sorted(range(n), key=lambda x: -len(adj[x]))
    col=[-1]*n
    def bt(idx):
        if idx==n: return True
        u=order[idx]
        used={col[v] for v in adj[u] if col[v]!=-1}
        for c in range(4):
            if c not in used:
                col[u]=c
                if bt(idx+1): return True
                col[u]=-1
        return False
    return bt(0), col

